const N=s=>s.toLowerCase().replace(/[‘’]/g,"'").replace(/[“”]/g,'"').replace(/ /g,' ').replace(/[–—]/g,'-').replace(/\s+/g,'');
const its=ITEMS[location.host]||[];if(!its.length)return 'NOITEMS '+location.host;
let P=null;const out=[];
for(const [id,u,parts] of its){try{
 let txt='';const here=location.href.split('#')[0].replace(/\/$/,'')===u.split('#')[0].replace(/\/$/,'');
 let st=200,fin='';
 if(here){txt=document.documentElement.textContent+' '+(document.body?document.body.innerText:'')}
 else{const r=await fetch(u,{credentials:'include'});st=r.status;if(r.url&&r.url.split('#')[0]!==u.split('#')[0])fin=r.url;const b=await r.arrayBuffer();const head=new TextDecoder().decode(b.slice(0,5));
  if(head==='%PDF-'){if(!P){P=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.379/pdf.min.mjs');P.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.379/pdf.worker.min.mjs'}
   const d=await P.getDocument({data:b}).promise;for(let k=1;k<=d.numPages;k++){const c=await (await d.getPage(k)).getTextContent();txt+=c.items.map(x=>x.str).join(' ')+' '}}
  else{const h=new TextDecoder().decode(b);const d=new DOMParser().parseFromString(h,'text/html');d.querySelectorAll('script,style').forEach(e=>e.remove());txt=d.documentElement.textContent}}
 const n=N(txt);const hit=parts.every(p=>n.includes(N(p)));
 let res=hit?'1':'0';
 if(!hit){const w=N(parts[0]).slice(0,28);const i=n.indexOf(w);if(i>=0)res='P['+n.slice(i,i+110)+']';}
 out.push(id+':'+res+(st!==200?' s'+st:'')+(hit?'':' len'+n.length)+(fin?' ->'+fin.slice(0,90):''));
}catch(e){out.push(id+':E '+String(e).slice(0,60))}}
return out.join(' | ');